#include <stdio.h>

int *max_row(int rows, int cols, int m[rows][cols]) {
    int best = 0;
    long long best_sum = 0;
    for (int r = 0; r < rows; r++) {
        long long sum = 0;
        for (int c = 0; c < cols; c++) {
            sum += m[r][c];
        }
        if (r == 0 || sum > best_sum) {
            best = r;
            best_sum = sum;
        }
    }
    return m[best];
}

int main(void) {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    int m[rows][cols];
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            scanf("%d", &m[r][c]);
        }
    }
    int *best = max_row(rows, cols, m);
    printf("%td\n", (best - &m[0][0]) / cols);
    for (int c = 0; c < cols; c++) {
        printf(c + 1 < cols ? "%d " : "%d\n", best[c]);
    }
    return 0;
}

