#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int *rows[20];
    for (int i = 0; i < n; i++) {
        rows[i] = malloc((i + 1) * sizeof *rows[i]);
        if (rows[i] == NULL) {
            for (int k = 0; k < i; k++) {
                free(rows[k]);
            }
            return 1;
        }
        rows[i][0] = 1;
        rows[i][i] = 1;
        for (int j = 1; j < i; j++) {
            rows[i][j] = rows[i - 1][j - 1] + rows[i - 1][j];
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            printf(j < i ? "%d " : "%d\n", rows[i][j]);
        }
    }
    for (int i = 0; i < n; i++) {
        free(rows[i]);
    }
    return 0;
}

