#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int r, c;
    scanf("%d %d", &r, &c);
    int (*a)[c] = malloc(r * sizeof *a);
    long long (*pre)[c + 1] = malloc((r + 1) * sizeof *pre);
    if (a == NULL || pre == NULL) {
        free(a);
        free(pre);
        return 1;
    }
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            scanf("%d", &a[i][j]);
        }
    }
    for (int i = 0; i <= r; i++) {
        for (int j = 0; j <= c; j++) {
            if (i == 0 || j == 0) {
                pre[i][j] = 0;
            } else {
                pre[i][j] = a[i - 1][j - 1] + pre[i - 1][j] + pre[i][j - 1] - pre[i - 1][j - 1];
            }
        }
    }
    int q;
    scanf("%d", &q);
    for (int k = 0; k < q; k++) {
        int r1, c1, r2, c2;
        scanf("%d %d %d %d", &r1, &c1, &r2, &c2);
        long long sum = pre[r2 + 1][c2 + 1] - pre[r1][c2 + 1] - pre[r2 + 1][c1] + pre[r1][c1];
        printf("%lld\n", sum);
    }
    free(a);
    free(pre);
    return 0;
}

